-- Display names for the broadcast tools (docs/broadcast-roles.md §2): Log is
-- On Air, Underwriting & Traffic is Traffic. Only the names people read
-- change; the keys (`log`, `underwriting`) and routes stay, the same way
-- Sourcework kept its `transcription` key. Guides that named the tools, or
-- the old producer role, are rewritten.

update public.tools
set name = 'On Air',
    description = 'The broadcast day: the program schedule, clocks, rundowns, the content library, and the DAD log.'
where key = 'log';

update public.tools
set name = 'Traffic',
    description = 'What must air and proof that it did: underwriters, agreements, copy, placement, exceptions, and affidavits.'
where key = 'underwriting';

select private.rc_release_guide(
  p_slug => 'log-npr-and-weather',
  p_tool_key => 'log',
  p_title => 'Sources: NPR and weather',
  p_summary => 'Check the outside feeds On Air reads, and look up a program''s NPR stories or the current forecast.',
  p_screen_keys => array['log.sources'],
  p_sort_order => 50,
  p_version_note => 'Renamed On Air and Traffic',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Sources tab holds the outside feeds On Air reads. It opens on one card per source, showing whether its saved data is current, when it was last updated, and what it holds. Select a card's "},{"type":"text","text":"Open","marks":[{"type":"bold"}]},{"type":"text","text":" button to go to that source's page, and "},{"type":"text","text":"← Sources","marks":[{"type":"bold"}]},{"type":"text","text":" to come back."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What the cards say"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Up to date","marks":[{"type":"bold"}]},{"type":"text","text":": the saved data is inside its normal refresh window."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stale","marks":[{"type":"bold"}]},{"type":"text","text":": the saved data is older than that, or the last refresh failed. What was saved is still shown."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Not fetched yet","marks":[{"type":"bold"}]},{"type":"text","text":": nothing has been read from this source so far."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Not configured","marks":[{"type":"bold"}]},{"type":"text","text":": the portal has no access set up for this source yet."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"NPR"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the NPR page, choose a program and a show date, then select "},{"type":"text","text":"Switch","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The table lists each story's estimated air time (marked with “~”, since NPR doesn't supply exact times), title, teaser, and length."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Refresh","marks":[{"type":"bold"}]},{"type":"text","text":" to pull the latest episode data."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The NPR card reports the most recently read episode. NPR is read one program and date at a time, so it is refreshed from the NPR page rather than the card."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Weather"}]},{"type":"paragraph","content":[{"type":"text","text":"The weather page shows the current forecast: any hazards, a short outlook, live-read and condensed text for on air, and the underlying details. Select "},{"type":"text","text":"Refresh","marks":[{"type":"bold"}]},{"type":"text","text":" on the page or on the weather card to force an update."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sources refresh themselves when you open them and their data is past its window. Refresh is a manual option, not something you need to do routinely."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A fetch failure shows as a plain message, with whatever was last read still on screen. No page goes blank because of a temporary outage."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"NPR's estimated times need a rundown to already exist for that program and date. Without one, the table has nothing to anchor its estimates to."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'log-schedule-a-program',
  p_tool_key => 'log',
  p_title => 'Schedule a program',
  p_summary => 'See the week, change when a program airs, edit a program''s details, and find programs that still need a clock.',
  p_screen_keys => array['log.program', 'log.program.schedule'],
  p_sort_order => 20,
  p_version_note => 'Renamed On Air and Traffic',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Programs is where the schedule and every clock are reached from. Scheduling and changing a clock are the program director's."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"See the schedule"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Week","marks":[{"type":"bold"}]},{"type":"text","text":" view shows the week as a grid, one column per day, with each program at its air time and the clock it runs on. Programs still on the shared placeholder clock are shaded amber. Select a block to see its details, then "},{"type":"text","text":"Edit schedule","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Open program","marks":[{"type":"bold"}]},{"type":"text","text":". Use Prev, Next, and Today to change the week. The "},{"type":"text","text":"List","marks":[{"type":"bold"}]},{"type":"text","text":" view shows the same programs as a table."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find what needs attention"}]},{"type":"paragraph","content":[{"type":"text","text":"In the list, "},{"type":"text","text":"Needs a clock","marks":[{"type":"bold"}]},{"type":"text","text":" shows the programs still on the placeholder clock, and "},{"type":"text","text":"Not scheduled","marks":[{"type":"bold"}]},{"type":"text","text":" shows programs with no current schedule. Clocks no program uses are listed under "},{"type":"text","text":"Unused clocks","marks":[{"type":"bold"}]},{"type":"text","text":" below the list."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Change when a program airs"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the program. Under "},{"type":"text","text":"When it airs","marks":[{"type":"bold"}]},{"type":"text","text":" each schedule shows its days and time; select "},{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":". The clock it runs on is changed in the same editor."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose the days, the start time, and the length. The quick buttons set weekdays, the weekend, or every day."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Set when the schedule starts and, if it stops, when it ends. Pick the clock it runs on."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check the preview on the right. It shows the times, the next airing, and whether another program airs at the same time on those days. An overlap is a warning; it doesn't stop you saving."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Save schedule","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Rundowns that were already generated keep the clock they were built from; a new clock applies to rundowns generated from then on."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add a schedule"}]},{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"+ Add a time","marks":[{"type":"bold"}]},{"type":"text","text":" on a program's page, choose its days, time, and clock, and save. If the clock doesn't exist yet, select "},{"type":"text","text":"Create a clock for this program","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a program's details"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Details","marks":[{"type":"bold"}]},{"type":"text","text":" panel on a program's page holds its name, kind, description, and NPR connection. The program director selects "},{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":" on the panel to change them in place, then "},{"type":"text","text":"Save changes","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Collection ID","marks":[{"type":"bold"}]},{"type":"text","text":" is NPR's ID for the program. With it set, On Air reads that day's NPR stories for the program's rundowns. Leave it blank to stop reading NPR for the program."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Feed's first hour (Eastern)","marks":[{"type":"bold"}]},{"type":"text","text":" only matters for NPR's multi-hour shows, whose hours alternate on the feed. It lines up NPR's hours with ours so estimated story times are right. Leave it on "},{"type":"text","text":"Same as our schedule","marks":[{"type":"bold"}]},{"type":"text","text":" unless NPR's first hour differs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Changing the collection ID clears the program's saved NPR stories from today on, so the next look fetches the new ones. Earlier dates keep what they had."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'underwriting-migrate-legacy-agreements',
  p_tool_key => 'underwriting',
  p_title => 'Migrate legacy agreements',
  p_summary => 'Load a manifest of existing agreements, match each to its signed document, import them as draft contracts, and review the results.',
  p_screen_keys => array['underwriting.migration'],
  p_sort_order => 90,
  p_version_note => 'Renamed On Air and Traffic',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Administrators use this screen to bring agreements from the station's legacy records into Traffic. Open it from the Contracts list: "},{"type":"text","text":"Migrate legacy records","marks":[{"type":"bold"}]},{"type":"text","text":". It lists every batch with how far along it is and what it needs next."},{"type":"text","text":" Agreements are the first of its two tabs; active copy from RadioTraffic comes in on the second, Copy."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Start a batch"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"New batch","marks":[{"type":"bold"}]},{"type":"text","text":", name the batch, and choose where the facts come from: "},{"type":"text","text":"A spreadsheet of agreements","marks":[{"type":"bold"}]},{"type":"text","text":" (recommended) or "},{"type":"text","text":"Documents only","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For a spreadsheet, choose the manifest CSV or paste its rows. Every row is checked before anything is saved. A row that can't be read, or whose sponsor isn't on file, is listed first. When a close name is on file, select "},{"type":"text","text":"Use it","marks":[{"type":"bold"}]},{"type":"text","text":"; otherwise add the underwriter under Underwriters and load the manifest again."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Load and continue","marks":[{"type":"bold"}]},{"type":"text","text":". Rows that still need a fix are left out."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The manifest needs the underwriter and the document's file name in each row; the order number, run dates, sponsorship total, contract type, Drive file id, documentation status, and notes are optional. "},{"type":"text","text":"Download a template","marks":[{"type":"bold"}]},{"type":"text","text":" gives the column names."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Choose the documents"}]},{"type":"paragraph","content":[{"type":"text","text":"Choose the folder of signed agreements. Each entry is matched to its file by name. Anything that didn't match cleanly is listed under "},{"type":"text","text":"Needs attention","marks":[{"type":"bold"}]},{"type":"text","text":" with what to do: use a close match, choose the file, pick which entry a shared file belongs to, or choose a copy under 10 MB. Files the manifest doesn't name can be imported too, with every fact read from the document."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Import"}]},{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Import","marks":[{"type":"bold"}]},{"type":"text","text":". Three agreements are read at a time, each the same way "},{"type":"text","text":"Create from the agreement","marks":[{"type":"bold"}]},{"type":"text","text":" reads a single order, and each takes a minute or two. Keep the page open until the run finishes, or select "},{"type":"text","text":"Stop after the ones reading","marks":[{"type":"bold"}]},{"type":"text","text":". If the reading service asks the portal to slow down, the run pauses and carries on by itself."}]},{"type":"paragraph","content":[{"type":"text","text":"The manifest's facts win over what the document says; the schedule comes from the document. Each entry becomes a draft contract, which schedules nothing until someone activates it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Review"}]},{"type":"paragraph","content":[{"type":"text","text":"The batch page opens on "},{"type":"text","text":"Needs a look","marks":[{"type":"bold"}]},{"type":"text","text":": drafts where the document disagrees with the manifest, or where an instruction couldn't be saved as a schedule line. Open a row to see each disagreement side by side, and select "},{"type":"text","text":"Enter on the schedule","marks":[{"type":"bold"}]},{"type":"text","text":" for the lines to enter by hand. "},{"type":"text","text":"Ready to activate","marks":[{"type":"bold"}]},{"type":"text","text":" means nothing was flagged; the draft still needs a look before it's activated. A failed entry shows why; fix the cause and select "},{"type":"text","text":"Run again","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Running it again"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Importing again never creates a second contract for an entry that already has one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Loading a corrected manifest under the same batch name updates entries that haven't been imported. Keep each row's key the same."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"To redo an imported entry, delete its draft contract; the entry can then be imported again."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A document that has already been imported, under any entry, is not imported again."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'underwriting-setup',
  p_tool_key => 'underwriting',
  p_title => 'Setup',
  p_summary => 'Inventory pools, industries, and the one-time imports from RadioTraffic.',
  p_screen_keys => array['underwriting.setup'],
  p_sort_order => 60,
  p_version_note => 'Renamed On Air and Traffic',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Setup holds the lists the rest of the tool depends on. Each card says whether it needs attention."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inventory pools","marks":[{"type":"bold"}]},{"type":"text","text":": what an order's “AM Drive” or “Carpool” means in On Air programs and time windows. A pool with no mapping can't be scheduled."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Industries","marks":[{"type":"bold"}]},{"type":"text","text":": the categories auto-fill uses to keep competing underwriters out of the same break."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Import agreements","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Import copy","marks":[{"type":"bold"}]},{"type":"text","text":": the one-time moves from RadioTraffic. Only administrators see these."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'log-read-a-clock',
  p_tool_key => 'log',
  p_title => 'Read a clock',
  p_summary => 'The timeline and ring diagrams, hours of a longer shift, floating breaks, and versions.',
  p_screen_keys => array['log.clock'],
  p_sort_order => 10,
  p_version_note => 'Renamed On Air and Traffic',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Open a clock from the program that airs on it: on the program's page, select "},{"type":"text","text":"Open clock","marks":[{"type":"bold"}]},{"type":"text","text":". The link at the top left of the clock's page goes back to that program."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Timeline and Ring"}]},{"type":"paragraph","content":[{"type":"text","text":"The diagram shows one hour of the clock. Switch between "},{"type":"text","text":"Timeline","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Ring","marks":[{"type":"bold"}]},{"type":"text","text":" at the top right of the diagram; both behave the same way."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The network's structure comes first: segments, newscasts (dark), and promos and credits. WUWF's local opportunities are marked in blue: a dashed outline for optional, solid for required."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hover over or tab to a slot to read its name, times, and length. Select a slot to fix it in the side panel and the slot list."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Slots list lists every slot. Hovering over a row highlights that slot in the diagram; selecting a row shows it in the side panel."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Shifts longer than an hour"}]},{"type":"paragraph","content":[{"type":"text","text":"When a program airs for more than an hour, the clock repeats every hour. Use the arrows beside "},{"type":"text","text":"Hour 1 of 2","marks":[{"type":"bold"}]},{"type":"text","text":" to step through the hours. The network structure is the same in each hour, but pinned content can differ, and a small number on a local slot shows how many items are pinned for the hour you're looking at."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Floating breaks"}]},{"type":"paragraph","content":[{"type":"text","text":"A break whose position isn't fixed appears as a shaded window. A dashed edge can move and a solid edge is fixed; the darker area is always part of the break. Select it to see when it can start and end and how long it can run."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Versions"}]},{"type":"paragraph","content":[{"type":"text","text":"Choose a version from the "},{"type":"text","text":"Version","marks":[{"type":"bold"}]},{"type":"text","text":" menu. A version can't be edited once it exists — a correction is a new version, started with "},{"type":"text","text":"+ New version","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Changing what WUWF can fill (program director)"}]},{"type":"paragraph","content":[{"type":"text","text":"Select a slot, then use the buttons in its panel: "},{"type":"text","text":"Edit eligibility","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Pin content","marks":[{"type":"bold"}]},{"type":"text","text":" on a local slot, or "},{"type":"text","text":"Mark eligible for local content","marks":[{"type":"bold"}]},{"type":"text","text":" on a network-only one. "},{"type":"text","text":"Remove","marks":[{"type":"bold"}]},{"type":"text","text":" takes a slot out of local eligibility."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'log-content-library',
  p_tool_key => 'log',
  p_title => 'Building the content library',
  p_summary => 'Find, add, and approve news, promos, and other spots, or import WUWF''s existing DAD cut library in bulk.',
  p_screen_keys => array['log.library'],
  p_sort_order => 10,
  p_version_note => 'Renamed On Air and Traffic',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The content library holds everything a rundown can pull from — news, promos, membership messages, PSAs, legal IDs, and more. Anyone with On Air access can add to it, not just the program director."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find an item"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Type in the search box to search titles, DAD cart numbers, and scripts. The list updates as you type; pressing Enter searches straight away."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clear the box to see the whole library again."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use the status chips (All, Approved, Draft, Retired) and the content type chips to narrow the list. Each status chip shows how many items it would show."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The library shows 25 items a page, newest first. The page links under the table move between pages."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add a content item"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the library, select "},{"type":"text","text":"+ New content item","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fill in a title, content type, summary, script, expected duration, and effective dates."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Create content item","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add its components"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the item's page, expand "},{"type":"text","text":"Add a component","marks":[{"type":"bold"}]},{"type":"text","text":" — choose a type (live intro, recorded audio, live outro, or an optional tag), a sequence, a duration, and a script. Select "},{"type":"text","text":"Add component","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A required component counts toward the item's total time; an optional one doesn't."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Approve it"}]},{"type":"paragraph","content":[{"type":"text","text":"An item starts as a draft. Set its status to Approved, in the Status panel on its page, before it can be picked for a rundown — only approved items are offered when filling a break."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Import WUWF's DAD cut library"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"From the library, open the import screen and upload the Standard Library export from DAD (Library screen → Generate Reports → Standard Library) — optionally with its companion Groups report."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Preview import","marks":[{"type":"bold"}]},{"type":"text","text":" to see the plan: new items, updates to existing ones, and anything it couldn't place."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Import","marks":[{"type":"bold"}]},{"type":"text","text":" to confirm."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"There's no audio upload here. WUWF's playback system (ENCO/DAD) is where recorded material actually plays from — a content item is metadata and a script, not an audio file."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Re-running the import later updates an already-imported item in place (matched by its DAD cart number) instead of creating a duplicate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Retiring stale content is an ordinary status change, not a delete — nothing in the library is ever removed outright."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'underwriting-dashboard',
  p_tool_key => 'underwriting',
  p_title => 'The dashboard',
  p_summary => 'What needs attention today, grouped by job: missed credits, scheduling, and affidavits.',
  p_screen_keys => array['underwriting.dashboard'],
  p_sort_order => 10,
  p_version_note => 'Renamed On Air and Traffic',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The dashboard opens on what needs attention, in three groups. Every number links to the list it counts, filtered the same way."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Missed credits"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Need a decision","marks":[{"type":"bold"}]},{"type":"text","text":": an exception with no makegood yet, or one the agency declined."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Waiting on the agency","marks":[{"type":"bold"}]},{"type":"text","text":": the order's makegoods need the agency's approval, and no answer is recorded yet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Makegoods awaiting a break","marks":[{"type":"bold"}]},{"type":"text","text":": the next auto-fill places these first."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Scheduling"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Units not yet scheduled","marks":[{"type":"bold"}]},{"type":"text","text":": open periods on active contracts that auto-fill hasn't reached yet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Capacity conflicts","marks":[{"type":"bold"}]},{"type":"text","text":": lines that can't be placed in the next 14 days, listed below with what's blocking each one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"To record in DAD","marks":[{"type":"bold"}]},{"type":"text","text":": messages under a new DAD cut that production hasn't marked recorded yet."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Affidavits"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"To generate","marks":[{"type":"bold"}]},{"type":"text","text":": contracts with aired credits not yet covered by an affidavit."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Awaiting your signature","marks":[{"type":"bold"}]},{"type":"text","text":": generated affidavits ready to sign. Only underwriting managers see this one."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Auto-fill everything","marks":[{"type":"bold"}]},{"type":"text","text":" in the right-hand column to fill every active contract's open periods, makegoods first."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If you can open On Air, "},{"type":"text","text":"Log of record","marks":[{"type":"bold"}]},{"type":"text","text":" in the right-hand column shows whether the DAD log is released for today and the next two days, and links to "},{"type":"text","text":"Station IDs","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-02-on-air-and-traffic',
  p_tool_key => 'log',
  p_released_on => '2026-10-02',
  p_title => 'Log is now On Air, and Underwriting & Traffic is now Traffic',
  p_guide_slugs => array['log-schedule-a-program', 'underwriting-dashboard'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The broadcast tools have names for what they hold. On Air is the broadcast day: the schedule, clocks, rundowns, and the DAD log. Traffic is what must air and the proof that it did: underwriters, agreements, copy, placement, exceptions, and affidavits. Addresses, bookmarks, and access are unchanged."}]}]}$body$
);
